// Generated by DeepSeek Electrical Systems Architect
export interface SubstationTelemetryData {
  gridVoltage110kV: number;
  tractionVoltage1200V: number;
  totalActivePowerMW: number;
  bessStateOfChargePct: number;
  bessPowerMW: number;
  co2SavedKgPerHour: number;
  dieselFuelSavedLitersPerHour: number;
  activeFeeders: string[];
  emergencyStatus: 'NORMAL' | 'CONTINGENCY_1200V' | 'PEAK_SHAVING' | 'ISLAND_MODE';
}

const NOMINAL_GRID_VOLTAGE_KV = 110.4;
const NOMINAL_TRACTION_VOLTAGE_V = 1220;

const TRACTION_PEAK_LOAD_MW = 6.4;
const TRACTION_SURGE_MW = 4.2;
const BESS_PEAK_SHAVE_MW = 2.1;
const BESS_CAPACITY_MWH = 2.0;
const BESS_MAX_POWER_MW = 4.0;

const SHOVEL_LOAD_MW = 2.8;
const CRUSHER_LOAD_MW = 1.6;
const SAG_MILL_LOAD_MW = 6.8;

const DIESEL_SAVED_L_PER_H = 380;
const CO2_SAVED_KG_PER_H = 1020;

const FEEDER_SHOVEL = '6kV-ЭКГ-15';
const FEEDER_CRUSHER = '6kV-ККД-1500';
const FEEDER_SAG = '6kV-МПСИ-90';
const FEEDER_TRACTION = '1200V-Троллей';
const FEEDER_BESS = '10kV-BESS';

function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

function round(value: number, decimals: number): number {
  const factor = Math.pow(10, decimals);
  return Math.round(value * factor) / factor;
}

function computeBaseLoadMW(simTime: number): number {
  const shovelCycle = 0.85 + 0.15 * Math.sin(simTime * 0.05);
  const crusherCycle = 0.9 + 0.1 * Math.sin(simTime * 0.03 + 1.2);
  const sagCycle = 0.92 + 0.08 * Math.sin(simTime * 0.02 + 2.4);
  return (
    SHOVEL_LOAD_MW * shovelCycle +
    CRUSHER_LOAD_MW * crusherCycle +
    SAG_MILL_LOAD_MW * sagCycle
  );
}

function computeTractionLoadMW(belazTrolleyActive: boolean, simTime: number): number {
  if (!belazTrolleyActive) {
    return 0.4 + 0.2 * Math.sin(simTime * 0.1);
  }
  const surgeFactor = 0.9 + 0.1 * Math.sin(simTime * 0.15);
  return TRACTION_PEAK_LOAD_MW * surgeFactor;
}

export function computeSubstationTelemetry(
  simTime: number,
  activeScenario: string | null,
  belazTrolleyActive: boolean,
): SubstationTelemetryData {
  const isContingency = activeScenario === 'sc_1200v_fault';
  const isIsland = activeScenario === 'sc_island_mode';

  const baseLoadMW = computeBaseLoadMW(simTime);
  const tractionLoadMW = isContingency ? 0 : computeTractionLoadMW(belazTrolleyActive, simTime);

  let bessPowerMW = 0;
  let bessStateOfChargePct = 62;
  let emergencyStatus: SubstationTelemetryData['emergencyStatus'] = 'NORMAL';
  let gridVoltage110kV = NOMINAL_GRID_VOLTAGE_KV;
  let tractionVoltage1200V = NOMINAL_TRACTION_VOLTAGE_V;

  const activeFeeders: string[] = [FEEDER_SHOVEL, FEEDER_CRUSHER, FEEDER_SAG];

  if (isContingency) {
    emergencyStatus = 'CONTINGENCY_1200V';
    tractionVoltage1200V = 0;
    gridVoltage110kV = NOMINAL_GRID_VOLTAGE_KV - 0.6;
    bessPowerMW = 0;
    bessStateOfChargePct = 58;
    activeFeeders.push(FEEDER_BESS);
  } else if (isIsland) {
    emergencyStatus = 'ISLAND_MODE';
    gridVoltage110kV = 0;
    tractionVoltage1200V = NOMINAL_TRACTION_VOLTAGE_V * 0.97;
    bessPowerMW = clamp(baseLoadMW + tractionLoadMW, 0, BESS_MAX_POWER_MW);
    bessStateOfChargePct = 45;
    activeFeeders.push(FEEDER_TRACTION, FEEDER_BESS);
  } else {
    activeFeeders.push(FEEDER_TRACTION, FEEDER_BESS);

    if (belazTrolleyActive) {
      bessPowerMW = BESS_PEAK_SHAVE_MW;
      emergencyStatus = 'PEAK_SHAVING';
      gridVoltage110kV = NOMINAL_GRID_VOLTAGE_KV - 0.15;
      bessStateOfChargePct = 55;
    } else {
      bessPowerMW = -0.8;
      bessStateOfChargePct = 68;
      gridVoltage110kV = NOMINAL_GRID_VOLTAGE_KV + 0.05;
    }
  }

  const totalActivePowerMW = round(baseLoadMW + tractionLoadMW, 2);

  const dieselFuelSavedLitersPerHour = belazTrolleyActive && !isContingency ? DIESEL_SAVED_L_PER_H : 0;
  const co2SavedKgPerHour = belazTrolleyActive && !isContingency ? CO2_SAVED_KG_PER_H : 0;

  return {
    gridVoltage110kV: round(gridVoltage110kV, 2),
    tractionVoltage1200V: round(tractionVoltage1200V, 1),
    totalActivePowerMW,
    bessStateOfChargePct: round(clamp(bessStateOfChargePct, 0, 100), 1),
    bessPowerMW: round(bessPowerMW, 2),
    co2SavedKgPerHour: round(co2SavedKgPerHour, 1),
    dieselFuelSavedLitersPerHour: round(dieselFuelSavedLitersPerHour, 1),
    activeFeeders,
    emergencyStatus,
  };
}

function statusLabel(status: SubstationTelemetryData['emergencyStatus']): string {
  switch (status) {
    case 'NORMAL':
      return 'НОРМА';
    case 'CONTINGENCY_1200V':
      return 'АВАРИЯ 1200В';
    case 'PEAK_SHAVING':
      return 'СГЛАЖИВАНИЕ ПИКОВ';
    case 'ISLAND_MODE':
      return 'ОСТРОВНОЙ РЕЖИМ';
    default:
      return 'НЕИЗВЕСТНО';
  }
}

function bessModeLabel(powerMW: number): string {
  if (powerMW > 0.05) return 'РАЗРЯД';
  if (powerMW < -0.05) return 'ЗАРЯД';
  return 'ОЖИДАНИЕ';
}

export function formatSubstationStatusReport(telemetry: SubstationTelemetryData): string {
  const lines: string[] = [];
  lines.push('=== ОПЕРАТИВНАЯ ТЕЛЕМЕТРИЯ ГПП 110/10 кВ ===');
  lines.push(`Статус: ${statusLabel(telemetry.emergencyStatus)}`);
  lines.push(`Напряжение сети 110 кВ: ${telemetry.gridVoltage110kV.toFixed(2)} кВ`);
  lines.push(`Напряжение тяги 1200 В: ${telemetry.tractionVoltage1200V.toFixed(1)} В`);
  lines.push(`Суммарная активная мощность: ${telemetry.totalActivePowerMW.toFixed(2)} МВт`);
  lines.push(
    `СНЭ (BESS): ${telemetry.bessStateOfChargePct.toFixed(1)} % | ` +
      `${bessModeLabel(telemetry.bessPowerMW)} ${Math.abs(telemetry.bessPowerMW).toFixed(2)} МВт`,
  );
  lines.push(`Активные фидеры: ${telemetry.activeFeeders.join(', ')}`);
  lines.push(
    `Экономия дизеля: ${telemetry.dieselFuelSavedLitersPerHour.toFixed(1)} л/ч | ` +
      `Снижение CO2: ${telemetry.co2SavedKgPerHour.toFixed(1)} кг/ч`,
  );
  return lines.join('\n');
}
